int build_proxy_rule(const char* target_host, const char* proxy_config, char* rule_buffer, size_t buffer_size) {
    if (target_host == NULL || proxy_config == NULL || rule_buffer == NULL || buffer_size == 0) {
        return -1;
    }

    // Initialize the buffer
    rule_buffer[0] = '\0';

    // Check if target_host is empty
    if (target_host[0] == '\0') {
        return -1;
    }

    // Check if proxy_config is empty
    if (proxy_config[0] == '\0') {
        return -1;
    }

    // Create a temporary buffer to check the total length
    size_t target_len = strlen(target_host);
    size_t config_len = strlen(proxy_config);
    size_t separator_len = 2; // for ":"

    // Total required length includes target_host + separator + proxy_config + null terminator
    if (target_len + separator_len + config_len + 1 > buffer_size) {
        return -1; // Buffer too small
    }

    // Start building the rule
    strcpy(rule_buffer, target_host);

    // Add separator
    strncat(rule_buffer, ":", buffer_size - strlen(rule_buffer) - 1);

    // Add proxy config
    strncat(rule_buffer, proxy_config, buffer_size - strlen(rule_buffer) - 1);

    return 0; // Success
}
